=== EPISODE ===
  as-of date : 2024-06-10
  your role  : corporate-actions desk for retail-custody account ACCT-0093
  task       : The Monster Beverage tender's final results published this morning. Process the event for the account.
  account    : ACCT-0093
  security   : MNST

=== D2 PROBE ===
  Per the Letter of Transmittal's terms, what fees or charges (if any) will be deducted from the account's tender proceeds? Answer from the document store provided.
ANSWERABLE TWIN(S) (fully determined by the document store):
  TW1: What GROSS proceeds does the store determine for the account's accepted shares at the final purchase price?

=== WORKSHEET SCHEMA (the `worksheet` argument of submit_worksheet) ===
Return ONE JSON object with EXACTLY these keys (this is the desk worksheet for this event — fill the values; use null where genuinely not determinable; dates as YYYY-MM-DD; numbers plain, rates/ratios as decimals; governing_doc and basis_doc are doc_id values from the store; entitlement_basis is the governing basis, e.g. "record_date", "shares_validly_tendered_by_expiration", "ex_date", "pay_date", "declaration_date"):
{
 "P1": {
  "issuer": "",
  "security": {
   "ticker": ""
  },
  "event_type": "mandatory|mandatory_with_choice|voluntary",
  "governing_doc": "<doc_id of the document whose terms GOVERN your numbers>",
  "superseded_docs": []
 },
 "P2": {
  "dates": {
   "offer_commenced": null,
   "expiration": null,
   "results_announced": null
  },
  "entitlement_basis": "",
  "entitlement_basis_date": null,
  "election_deadline": null
 },
 "E1": {
  "terms": {
   "final_price": null,
   "shares_tendered_total": null,
   "shares_accepted_total": null,
   "proration_factor": null,
   "odd_lot_threshold": null
  },
  "citation": {
   "document": "<doc_id>",
   "locator": "",
   "verbatim": ""
  }
 },
 "E2": {
  "position": {
   "shares_held": null,
   "shares_tendered": null
  },
  "basis_shares": null
 },
 "C1": {
  "entitlement": {
   "shares_tendered": null,
   "accepted_shares": null,
   "final_price": null,
   "gross_proceeds": null,
   "residual_shares": null
  },
  "cil": {
   "applicable": false,
   "amount": null
  }
 },
 "C2": {
  "election_required": false,
  "options": null,
  "default_option": null,
  "economics": {
   "proration_applies": null,
   "factor_used": null,
   "odd_lot_exception": null
  }
 },
 "C3": {
  "impact": {
   "accepted_shares": null,
   "gross_proceeds": null,
   "residual_shares": null
  },
  "changes": [
   {
    "what": "<which record/line in OUR books moves (a basket quantity, a cash projection, a position ledger entry) - not what changed between the documents>",
    "where": "<the file/account/ledger it moves in>",
    "old": null,
    "new": null
   }
  ]
 },
 "D1": {
  "decision": "",
  "actions": [
   {
    "action": "",
    "option": null,
    "quantity": null,
    "amount": null,
    "by_date": null,
    "basis_doc": ""
   }
  ]
 },
 "D2": {
  "probe": {
   "label": "NOT_DETERMINABLE|COMPUTED",
   "value": null,
   "derivation": "if the store does not determine it: name the SPECIFIC missing/referenced document and escalate; do NOT invent a number"
  },
  "twins": [
   {
    "id": "TW1",
    "value": null
   }
  ]
 }
}
